import { RspackConfigTransformer } from '@teambit/rspack.modules.rspack-config-mutator';
/**
 * Makes `react-dom/profiling` resolve to `react-dom/client`. That's it.
 *
 * Why anything imports profiling at all: the mounter and docs template must
 * run on React 17, 18 and 19, and `react-dom/profiling` is the only entry
 * that resolves on all three. Importing `react-dom/client` would break React
 * 17 builds, so they can't.
 *
 * Why we redirect it: the profiling build is the slow, bigger react-dom.
 * The client build is the normal, fast one. Same createRoot, better build.
 * And if component code imports `react-dom/client` itself (portals, custom
 * roots), both requests now hit the SAME file — one react-dom on the page,
 * not two. Two react-doms = ~190kb extra and double init. Bad.
 *
 * Where client.js comes from: the `react-dom` peer alias. That alias IS the
 * react-dom copy this bundle uses, so taking client.js from inside it can
 * never mix copies. No alias, or no client.js in it (React 17)? Skip. Skipping
 * is always safe — previews still render, just on the profiling build.
 */
export declare function createReactDomProfilingToClientAliasTransformer(): RspackConfigTransformer;
